import{_ as e}from"./chunks/drivers-and-rosters._vhNWDjg.js";import{_ as r,o as t,c as s,a2 as l}from"./chunks/framework.CWgsre3x.js";const m=JSON.parse('{"title":"Οδηγοί και βάρδιες","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/drivers-and-rosters.md","filePath":"el/plus/drivers-and-rosters.md"}'),i={name:"el/plus/drivers-and-rosters.md"};function o(n,a,d,h,p,c){return t(),s("div",null,[...a[0]||(a[0]=[l('<h1 id="οδηγοι-και-βαρδιες" tabindex="-1">Οδηγοί και βάρδιες <a class="header-anchor" href="#οδηγοι-και-βαρδιες" aria-label="Permalink to &quot;Οδηγοί και βάρδιες&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>TransferBook+ v0.7.9: προσχέδιο ελεγμένο στον πηγαίο κώδικα. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις· δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/drivers-and-rosters.png"><img src="'+e+'" alt="Οδηγοί και βάρδιες: διαθεσιμότητα, γλώσσες, ανάθεση οχήματος και στοιχεία προφίλ. Τα στοιχεία επικοινωνίας και άδειας έχουν καλυφθεί."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Οδηγοί και βάρδιες: διαθεσιμότητα, γλώσσες, ανάθεση οχήματος και στοιχεία προφίλ. Τα στοιχεία επικοινωνίας και άδειας έχουν καλυφθεί.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή. Έχουν καλυφθεί αναγνωριστικά στοιχεία.</p><p>Διατηρήστε τα προφίλ οδηγών και τις βάρδιες σύμφωνα με την πραγματική λειτουργία.</p><h2 id="πριν-ξεκινησετε" tabindex="-1">Πριν ξεκινήσετε <a class="header-anchor" href="#πριν-ξεκινησετε" aria-label="Permalink to &quot;Πριν ξεκινήσετε&quot;">​</a></h2><p>Χρησιμοποιήστε εγκεκριμένο περιβάλλον, επιβεβαιώστε εταιρεία και ρόλο και χρησιμοποιήστε συνθετικά στοιχεία για εκπαίδευση.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Στο Chauffeurs &amp; Crew Management αναζητήστε όνομα, άδεια, γλώσσα ή περιοχή. Φιλτράρετε με On Duty, Busy / On Transfer ή Off Duty.</li><li>Χρησιμοποιήστε Add Chauffeur ή Edit Chauffeur εφόσον έχετε δικαιώματα. Ελέγξτε περιοχή, επικοινωνία, κατηγορία και λήξη άδειας, επαγγελματική άδεια, γλώσσες και διαθεσιμότητα. Καταχωρίστε μόνο επαληθευμένα στοιχεία.</li><li>Στο πρόγραμμα επιλέξτε οδηγό, τύπο βάρδιας (Active Shift, Airport Standby, Day Off ή Absence / Leave), ημερομηνίες και ώρες. Προσθέστε προαιρετική σημείωση και ελέγξτε την αποθηκευμένη εγγραφή.</li></ol><h2 id="επαληθευση-και-αντιμετωπιση-προβληματων" tabindex="-1">Επαλήθευση και αντιμετώπιση προβλημάτων <a class="header-anchor" href="#επαληθευση-και-αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Επαλήθευση και αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Η βάρδια δεν είναι ανάθεση διαδρομής. Ελέγξτε ξεχωριστά τις συγκρούσεις. Το προφίλ δεν αποδεικνύει ισχύ άδειας ή πρόσβαση λογαριασμού. Μην επινοείτε στοιχεία.</p><h2 id="σχετικοι-οδηγοι" tabindex="-1">Σχετικοί οδηγοί <a class="header-anchor" href="#σχετικοι-οδηγοι" aria-label="Permalink to &quot;Σχετικοί οδηγοί&quot;">​</a></h2><ul><li><a href="/el/plus/">Εγχειρίδιο χειριστή</a></li><li><a href="/el/plus/reservations.html">Κρατήσεις</a></li><li><a href="/el/plus/dispatch-schedule.html">Πρόγραμμα αναθέσεων</a></li></ul>',16)])])}const _=r(i,[["render",o]]);export{m as __pageData,_ as default};
